package com.avizero.avidrive.api;

import com.avizero.avidrive.domain.Folder; import com.avizero.avidrive.domain.StoredFile; import com.avizero.avidrive.repository.FolderRepository; import com.avizero.avidrive.repository.StoredFileRepository; import com.avizero.avidrive.security.AuthUser;
import jakarta.transaction.Transactional; import java.time.Instant; import java.util.*; import org.springframework.http.ResponseEntity; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;

@RestController @RequestMapping("/api") public class FileManagerController {
    private final FolderRepository folders; private final StoredFileRepository files;
    public FileManagerController(FolderRepository folders,StoredFileRepository files){this.folders=folders;this.files=files;}
    @GetMapping("/files") public Map<String,Object> list(@RequestParam(required=false) Long folder_id,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="50")int size,@RequestParam(defaultValue="name")String sort,@RequestParam(defaultValue="asc")String direction,@RequestParam(defaultValue="all")String filter,Authentication a){
        Long owner=id(a); List<Map<String,Object>> result=new ArrayList<>(); if(!"files".equals(filter))folders.findByOwnerIdAndParentId(owner,folder_id).forEach(f->result.add(item(f))); if(!"folders".equals(filter))files.findByOwnerIdAndFolderId(owner,folder_id).forEach(f->result.add(item(f))); result.sort(Comparator.comparing(x->String.valueOf(x.getOrDefault(sort,"")),String.CASE_INSENSITIVE_ORDER));if("desc".equalsIgnoreCase(direction))Collections.reverse(result);int from=Math.min(Math.max(page-1,0)*Math.max(size,1),result.size()),to=Math.min(from+Math.max(size,1),result.size());return Map.of("items",result.subList(from,to),"total",result.size(),"page",page,"pages",(result.size()+Math.max(size,1)-1)/Math.max(size,1));
    }
    @GetMapping("/folders/{id}/path") public ResponseEntity<?> path(@PathVariable Long id,Authentication a){Folder current=ownedFolder(id,a);if(current==null)return error(404,"Папка не найдена");List<Map<String,Object>> path=new ArrayList<>();while(current!=null){path.add(0,Map.of("id",current.id,"name",current.name));current=current.parentId==null?null:folders.findById(current.parentId).orElse(null);}return ResponseEntity.ok(path);}
    @PostMapping("/folders") public ResponseEntity<?> createFolder(@RequestBody FolderRequest r,Authentication a){Long owner=id(a);if(!validName(r.name()))return error(400,"Имя содержит запрещённые символы");if(r.parent_id()!=null&&ownedFolder(r.parent_id(),a)==null)return error(404,"Папка не найдена");if(folders.existsByOwnerIdAndParentIdAndName(owner,r.parent_id(),r.name()))return error(409,"Объект уже существует");Folder f=new Folder();f.ownerId=owner;f.parentId=r.parent_id();f.name=r.name();f.createdAt=Instant.now().toString();return ResponseEntity.ok(folders.save(f));}
    @PatchMapping("/folders/{id}") public ResponseEntity<?> renameFolder(@PathVariable Long id,@RequestBody RenameRequest r,Authentication a){Folder f=ownedFolder(id,a);if(f==null)return error(404,"Папка не найдена");if(!validName(r.name()))return error(400,"Имя содержит запрещённые символы");if(folders.existsByOwnerIdAndParentIdAndName(f.ownerId,f.parentId,r.name()))return error(409,"Объект уже существует");f.name=r.name();return ResponseEntity.ok(folders.save(f));}
    @PatchMapping("/files/{id}") public ResponseEntity<?> renameFile(@PathVariable Long id,@RequestBody RenameRequest r,Authentication a){StoredFile f=ownedFile(id,a);if(f==null)return error(404,"Файл не найден");if(!validName(r.name()))return error(400,"Имя содержит запрещённые символы");if(files.existsByOwnerIdAndFolderIdAndName(f.ownerId,f.folderId,r.name()))return error(409,"Объект уже существует");f.name=r.name();return ResponseEntity.ok(files.save(f));}
    @PostMapping("/files/move") public ResponseEntity<?> move(@RequestBody MoveRequest r,Authentication a){Long owner=id(a);if(r.target_folder_id()!=null&&ownedFolder(r.target_folder_id(),a)==null)return error(404,"Папка назначения не найдена");for(Long fid:r.file_ids()==null?List.<Long>of():r.file_ids()){StoredFile f=ownedFile(fid,a);if(f==null)return error(404,"Файл не найден");f.folderId=r.target_folder_id();files.save(f);}for(Long did:r.folder_ids()==null?List.<Long>of():r.folder_ids()){Folder f=ownedFolder(did,a);if(f==null)return error(404,"Папка не найдена");if(did.equals(r.target_folder_id())||descendant(did,r.target_folder_id()))return error(409,"Нельзя переместить папку внутрь себя");f.parentId=r.target_folder_id();folders.save(f);}return ResponseEntity.ok(Map.of("status","OK"));}
    @DeleteMapping("/files/bulk") @Transactional public ResponseEntity<?> delete(@RequestBody MoveRequest r,Authentication a){for(Long id:r.file_ids()==null?List.<Long>of():r.file_ids()){StoredFile f=ownedFile(id,a);if(f==null)return error(404,"Файл не найден");files.delete(f);}for(Long id:r.folder_ids()==null?List.<Long>of():r.folder_ids()){Folder f=ownedFolder(id,a);if(f==null)return error(404,"Папка не найдена");folders.delete(f);}return ResponseEntity.noContent().build();}
    @GetMapping("/files/{id}") public ResponseEntity<?> properties(@PathVariable Long id,Authentication a){StoredFile f=ownedFile(id,a);if(f!=null)return ResponseEntity.ok(Map.of("id",f.id,"type","FILE","name",f.name,"size_bytes",f.sizeBytes,"mime_type",f.mimeType,"owner_id",f.ownerId));Folder d=ownedFolder(id,a);if(d!=null)return ResponseEntity.ok(Map.of("id",d.id,"type","FOLDER","name",d.name,"owner_id",d.ownerId));return error(404,"Объект не найден");}
    private boolean descendant(Long folder,Long target){while(target!=null){if(folder.equals(target))return true;target=folders.findById(target).map(x->x.parentId).orElse(null);}return false;} private Long id(Authentication a){return ((AuthUser)a.getPrincipal()).id();} private Folder ownedFolder(Long id,Authentication a){return id==null?null:folders.findById(id).filter(x->x.ownerId.equals(id(a))).orElse(null);} private StoredFile ownedFile(Long id,Authentication a){return files.findById(id).filter(x->x.ownerId.equals(this.id(a))).orElse(null);} private boolean validName(String n){return n!=null&&!n.isBlank()&&!n.matches(".*[\\\\/:*?\"<>|].*")&&!n.contains("..")&&n.length()<=255;} private Map<String,Object> item(Folder f){return Map.of("id",f.id,"type","FOLDER","name",f.name,"size_bytes",0,"mime_type", "inode/directory","updated_at",Instant.now().toString(),"is_shared",f.shared);} private Map<String,Object> item(StoredFile f){return Map.of("id",f.id,"type","FILE","name",f.name,"size_bytes",f.sizeBytes==null?0:f.sizeBytes,"mime_type",f.mimeType==null?"application/octet-stream":f.mimeType,"updated_at",Instant.now().toString(),"is_shared",false);} private ResponseEntity<Map<String,String>> error(int s,String m){return ResponseEntity.status(s).body(Map.of("message",m));}
    public record FolderRequest(Long parent_id,String name){} public record RenameRequest(String name){} public record MoveRequest(List<Long> file_ids,List<Long> folder_ids,Long target_folder_id){}
}
